/* Operation Ascend B2.1: partner pipeline. Same black, charcoal, restrained gold and silver as the Empower partner surfaces. */
.pl-summary{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,150px),1fr));gap:12px;margin:0 0 20px}
.pl-summary div{border:1px solid #33343a;border-radius:12px;background:linear-gradient(180deg,#1c1d21,#17181b);padding:14px 16px}
.pl-summary dt{font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:#b9bec8}
.pl-summary dd{margin:4px 0 0;font-size:26px;font-weight:650;color:#f1e2b8;font-variant-numeric:tabular-nums}
.pl-toolbar{display:flex;flex-wrap:wrap;gap:12px;align-items:flex-end;margin:0 0 8px;padding:14px;border:1px solid #2e2f34;border-radius:12px;background:#151619}
.pl-field{display:flex;flex-direction:column;gap:6px;font-size:12px;color:#c9cdd5;min-width:0}
.pl-field span{letter-spacing:.02em}
.pl-field input,.pl-field select,.pl-field textarea{min-height:44px;padding:8px 12px;border-radius:9px;border:1px solid #45464d;background:#0f1012;color:#eef0f3;font:inherit;font-size:14px;max-width:100%}
.pl-field textarea{min-height:88px;resize:vertical}
.pl-field input:focus-visible,.pl-field select:focus-visible,.pl-field textarea:focus-visible,.pl-check input:focus-visible{outline:2px solid #d9bf83;outline-offset:2px}
.pl-search{flex:1 1 220px}
.pl-check{display:inline-flex;align-items:center;gap:8px;min-height:44px;font-size:13px;color:#d6d9df;cursor:pointer}
.pl-check input{width:20px;height:20px;accent-color:#cfb578}
.pl-views{display:inline-flex;border:1px solid #45464d;border-radius:10px;overflow:hidden;margin-left:auto}
.pl-views button{min-height:44px;min-width:64px;padding:0 14px;border:0;background:transparent;color:#c9cdd5;font:inherit;font-size:13px;cursor:pointer}
.pl-views button+button{border-left:1px solid #45464d}
.pl-views button[aria-pressed="true"]{background:#cfb578;color:#161616;font-weight:650}
.pl-views button:focus-visible{outline:2px solid #d9bf83;outline-offset:-3px}
.pl-live{min-height:20px;margin:6px 0 12px;font-size:12px;color:#9aa1ad}
.pl-board{display:grid;grid-auto-flow:column;grid-auto-columns:minmax(240px,1fr);gap:12px;overflow-x:auto;padding-bottom:12px;scroll-snap-type:x proximity}
.pl-column{border:1px solid #2e2f34;border-radius:12px;background:#141518;padding:12px;min-width:0;scroll-snap-align:start}
.pl-column header h2{margin:0;font-size:14px;color:#f1f2f5;display:flex;align-items:center;gap:8px}
.pl-column header p{margin:4px 0 10px;font-size:12px;color:#9aa1ad;line-height:1.5}
.pl-count{font-size:11px;border:1px solid #6b5a39;color:#e2cb93;border-radius:999px;padding:0 8px;font-variant-numeric:tabular-nums}
.pl-column ul,.pl-list{list-style:none;margin:0;padding:0;display:grid;gap:8px}
.pl-none{margin:0;font-size:12px;color:#7f8692}
.pl-card{display:flex;flex-direction:column;align-items:flex-start;gap:4px;width:100%;text-align:left;padding:12px;border:1px solid #33343a;border-radius:10px;background:linear-gradient(180deg,#1c1d21,#17181b);color:#e8eaee;font:inherit;cursor:pointer;transition:border-color .16s ease,transform .16s ease}
.pl-card:hover{border-color:#6b5a39;transform:translateY(-1px)}
.pl-card:focus-visible,.pl-rowlink:focus-visible,.pl-table-wrap:focus-visible{outline:2px solid #d9bf83;outline-offset:2px}
.pl-card strong{font-size:14px;color:#f4f5f7;overflow-wrap:anywhere}
.pl-status{font-size:12px;color:#d8bd84}
.pl-meta{font-size:12px;color:#9aa1ad}
.pl-flags{display:flex;flex-wrap:wrap;gap:6px}
.pl-flag{font-size:11px;border-radius:999px;padding:2px 8px;border:1px solid #4b4c52;color:#c9cdd5}
.pl-flag[data-tone="action"]{border-color:#8a6d33;color:#f0d9a2;background:#231d12}
.pl-flag[data-tone="done"]{border-color:#3f6b4f;color:#b6e3c5}
.pl-table-wrap{overflow-x:auto;border:1px solid #2e2f34;border-radius:12px}
.pl-table{width:100%;border-collapse:collapse;font-size:13px;color:#d6d9df;min-width:760px}
.pl-table th,.pl-table td{padding:10px 12px;border-bottom:1px solid #26272b;text-align:left;vertical-align:top}
.pl-table thead th{font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:#b9bec8;background:#141518;position:sticky;top:0}
.pl-table tbody tr:hover{background:#18191c}
.pl-rowlink{background:none;border:0;padding:0;min-height:44px;color:#e2cb93;font:inherit;font-weight:600;text-align:left;cursor:pointer;text-decoration:underline;text-underline-offset:4px}
.pl-empty{display:flex;flex-direction:column;gap:6px}
.pl-overlay{position:fixed;inset:0;z-index:50;background:rgba(5,5,6,.72);display:flex;justify-content:flex-end}
.pl-dialog{width:min(720px,100%);height:100%;overflow-y:auto;background:#121315;border-left:1px solid #34353a;padding:20px 20px 40px;box-shadow:-30px 0 60px -30px #000;animation:pl-in .18s ease-out}
.pl-dialog:focus{outline:none}
.pl-dialog-head{display:flex;justify-content:space-between;gap:12px;align-items:flex-start;position:sticky;top:-20px;background:#121315;padding:20px 0 8px;margin-top:-20px;z-index:1}
.pl-dialog-head h2{margin:2px 0 0;font-size:20px;color:#f4f5f7;overflow-wrap:anywhere}
.pl-block{border-top:1px solid #26272b;padding:14px 0}
.pl-actions{display:flex;flex-wrap:wrap;gap:8px}
.pl-why summary{cursor:pointer;min-height:44px;display:inline-flex;align-items:center;color:#e2cb93;font-size:13px}
.pl-why summary:focus-visible{outline:2px solid #d9bf83;outline-offset:2px;border-radius:4px}
.pl-why ul{margin:4px 0 0;padding-left:18px;font-size:13px;line-height:1.6;color:#c2c7cf}
.pl-forms{display:grid;gap:0}
.pl-form{display:grid;gap:10px}
.pl-form .gd-button{justify-self:start}
.pl-interactions{list-style:none;margin:0;padding:0;display:grid;gap:10px}
.pl-interactions li{border:1px solid #2e2f34;border-radius:10px;padding:10px 12px}
.pl-text{margin:4px 0 0;font-size:13px;line-height:1.6;color:#dfe2e7;white-space:pre-wrap;overflow-wrap:anywhere}
.pl-timeline{list-style:none;margin:0;padding:0 0 0 14px;border-left:1px solid #4a4030;display:grid;gap:10px}
.pl-timeline li{display:grid;grid-template-columns:auto 1fr auto;gap:10px;font-size:13px;color:#dfe2e7;position:relative}
.pl-timeline li::before{content:"";position:absolute;left:-19px;top:6px;width:9px;height:9px;border-radius:50%;background:#cfb578}
.pl-timeline time{color:#9aa1ad;font-variant-numeric:tabular-nums}
.pl-who{font-size:11px;color:#b9bec8}
.pl-dialog button:disabled{opacity:.55;cursor:not-allowed}
@keyframes pl-in{from{transform:translateX(24px);opacity:0}to{transform:none;opacity:1}}
@media (max-width:719px){
  .pl-views{margin-left:0}
  .pl-timeline li{grid-template-columns:1fr}
  .pl-dialog{padding:16px 16px 32px}
  .pl-dialog-head{top:-16px;padding-top:16px;margin-top:-16px}
}
@media (prefers-reduced-motion:reduce){.pl-card,.pl-dialog{transition:none;animation:none}.pl-card:hover{transform:none}}

